#!/usr/bin/env python3
"""Compute numeric ground truth for CSX-159_Q1."""

from __future__ import annotations

import html
import json
import re
from datetime import date
from pathlib import Path
from typing import Any


TASK_ID = "CSX-159_Q1"
EVENT_ID = "CSX-159"
INCH_TO_MM = 25.4
ANSWER_LABEL = "extreme_persistent_rainfall_deficit_water_supply_drought"
MONTHS = {
    "January": 1,
    "February": 2,
    "March": 3,
    "April": 4,
    "May": 5,
    "June": 6,
    "July": 7,
    "August": 8,
    "September": 9,
    "October": 10,
    "November": 11,
    "December": 12,
}


def repo_root() -> Path:
    return Path(__file__).resolve().parents[3]


def task_root() -> Path:
    return Path(__file__).resolve().parent


def package_root() -> Path:
    return repo_root() / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID


def read_json(rel_path: str) -> Any:
    with (package_root() / rel_path).open("r", encoding="utf-8-sig") as f:
        return json.load(f)


def read_text(rel_path: str) -> str:
    return (package_root() / rel_path).read_text(encoding="utf-8-sig", errors="replace")


def html_to_text(rel_path: str) -> str:
    raw = read_text(rel_path)
    text = re.sub(r"<script\b.*?</script>", " ", raw, flags=re.IGNORECASE | re.DOTALL)
    text = re.sub(r"<style\b.*?</style>", " ", text, flags=re.IGNORECASE | re.DOTALL)
    text = re.sub(r"<[^>]+>", " ", text)
    text = html.unescape(text)
    return re.sub(r"\s+", " ", text).strip()


def require_float(pattern: str, text: str, name: str) -> float:
    match = re.search(pattern, text, flags=re.IGNORECASE)
    if not match:
        raise ValueError(f"Could not extract {name}")
    return float(match.group(1))


def inclusive_days(start: str, end: str) -> int:
    start_date = date.fromisoformat(start)
    end_date = date.fromisoformat(end)
    return (end_date - start_date).days + 1


def extract_publication_date(text: str) -> str:
    match = re.search(
        r"Published\s+([A-Z][a-z]+)\s+([0-9]{1,2}),\s+([0-9]{4})",
        text,
    )
    if not match:
        raise ValueError("Could not extract NOAA publication date")
    month, day, year = match.groups()
    return date(int(year), MONTHS[month], int(day)).isoformat()


def rounded(value: float, digits: int) -> float:
    return round(value + 0.0, digits)


def main() -> None:
    anchor_path = (
        "data/event_reports/"
        "event_reports_003_Locked_event_anchor_2015-2016_El_Nino_drought_in_western_Pacific_island_capitals.json"
    )
    noaa_path = "data/event_reports/event_reports_001_Locked_anchor_report_NOAA_Climate.gov.html"

    anchor = read_json(anchor_path)
    noaa_text = html_to_text(noaa_path)

    event_window = anchor["temporal_window"]
    report_effective_end = extract_publication_date(noaa_text)
    event_window_core = {
        "start_date": event_window["start_date"],
        "end_date": report_effective_end,
        "anchor_end_date": event_window["end_date"],
        "end_date_basis": "NOAA report publication date for the 'since January' rainfall statement",
    }
    window_days = inclusive_days(event_window_core["start_date"], event_window_core["end_date"])

    observed_inches = require_float(
        r"only about ([0-9]+(?:\.[0-9]+)?) inches of rain (?:have )?fallen",
        noaa_text,
        "observed rainfall inches",
    )
    deficit_inches = require_float(
        r"nearly ([0-9]+(?:\.[0-9]+)?) inches below average",
        noaa_text,
        "below-average rainfall inches",
    )
    record_low_years = require_float(
        r"lowest recorded rainfall in ([0-9]+(?:\.[0-9]+)?) years",
        noaa_text,
        "record-low span years",
    )

    normal_inches = observed_inches + deficit_inches
    observed_mm = observed_inches * INCH_TO_MM
    deficit_mm = deficit_inches * INCH_TO_MM
    normal_mm = normal_inches * INCH_TO_MM

    rates = {
        "observed": rounded(observed_mm / window_days, 2),
        "deficit": rounded(deficit_mm / window_days, 2),
        "inferred_normal": rounded(normal_mm / window_days, 2),
    }

    observed_fraction = observed_inches / normal_inches
    deficit_index = deficit_inches / normal_inches
    stress_score = deficit_index * min(window_days / 90, 1) * min(record_low_years / 50, 1)

    threshold_result = {
        "duration_ge_90": window_days >= 90,
        "observed_fraction_le_0_30": observed_fraction <= 0.30,
        "deficit_index_ge_0_70": deficit_index >= 0.70,
        "record_years_ge_50": record_low_years >= 50,
        "interpretation": (
            f"Observed rain was 27% of normal for {window_days} days with a 559 mm deficit, "
            "meeting every persistence and severity test."
        ),
    }

    primary_gt = {
        "answer": ANSWER_LABEL,
        "window_days": window_days,
        "rainfall_ledger_mm": {
            "observed": rounded(observed_mm, 1),
            "deficit": rounded(deficit_mm, 1),
            "inferred_normal": rounded(normal_mm, 1),
        },
        "rates_mm_day": rates,
        "indices": {
            "observed_fraction": rounded(observed_fraction, 3),
            "deficit_index": rounded(deficit_index, 3),
            "stress_score": rounded(stress_score, 3),
        },
        "threshold_result": threshold_result,
    }

    output = {
        "schema_version": "1.0",
        "task_version": "numeric_v1",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "numeric",
        "evaluation_mode": "deterministic",
        "difficulty_level": "L3",
        "target_family": "koror_rainfall_deficit_water_balance_numeric_diagnosis",
        "primary_gt": primary_gt,
        "event": {
            "package_id": EVENT_ID,
            "event_name": anchor["event_name"],
            "hazard_family": anchor["hazard_family"],
            "event_date_or_window": f"{event_window_core['start_date']} to {event_window_core['end_date']}",
        },
        "formula_definitions": {
            "window_days": "inclusive days from event start through event end",
            "normal_rain_inches": "observed_rain_inches + below_average_inches",
            "observed_fraction": "observed_rain_inches / normal_rain_inches",
            "deficit_index": "below_average_inches / normal_rain_inches",
            "stress_score": "deficit_index * min(window_days / 90, 1) * min(record_low_years / 50, 1)",
        },
        "classification_rule": {
            "label_if_all_tests_pass": ANSWER_LABEL,
            "tests": {
                "window_days": ">= 90",
                "observed_fraction": "<= 0.30",
                "deficit_index": ">= 0.70",
                "record_low_years": ">= 50",
            },
        },
        "numeric_tolerances": {
            "window_days": 0,
            "rainfall_depth_mm": 0.1,
            "rates_mm_day": 0.02,
            "fractions_and_indices": 0.005,
            "record_low_years": 0,
            "boolean_thresholds": "exact",
        },
        "key_values": {
            "raw_inputs": {
                "event_window": event_window_core,
                "observed_rain_inches": observed_inches,
                "below_average_inches": deficit_inches,
                "record_low_years": record_low_years,
            },
            "derived_inches": {
                "inferred_normal_rain_inches": rounded(normal_inches, 1),
                "deficit_to_observed_ratio": rounded(deficit_inches / observed_inches, 3),
            },
            "derived_mm": primary_gt["rainfall_ledger_mm"],
            "rates_mm_day": rates,
            "indices": primary_gt["indices"],
            "threshold_result": threshold_result,
            "report_signal_checks": {
                "mentions_shifted_walker_circulation": "shifted Walker Circulation" in noaa_text,
                "mentions_extreme_drought": "extreme drought" in noaa_text,
                "mentions_water_rationing": "water rationing has begun" in noaa_text,
            },
        },
        "required_output_fields": [
            "answer",
            "window_days",
            "rainfall_ledger_mm",
            "rates_mm_day",
            "indices",
            "threshold_result",
        ],
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "answer_schema_and_units",
                    "points": 4,
                    "description": "Returns the requested six-field JSON, keeps millimeters and millimeters per day distinct, and includes a numeric interpretation sentence.",
                    "partial_credit": "Award 2-3 points if the JSON is mostly complete but one nested block or unit label is missing; award 1 point if the classification is present but the ledger shape is not usable.",
                },
                {
                    "name": "rainfall_ledger",
                    "points": 5,
                    "description": "Extracts 8 inches observed, 22 inches below average, computes 30 inches inferred normal, and converts to 203.2 mm, 558.8 mm, and 762.0 mm.",
                    "partial_credit": "Award 3-4 points for correct inch values with one conversion or inferred-normal error; award 1-2 points for using the right quantities but leaving them in inches or mixing observed and deficit depths.",
                },
                {
                    "name": "duration_and_rates",
                    "points": 3,
                    "description": "Computes the inclusive 111-day report-effective window and daily rates near 1.83, 5.03, and 6.86 mm/day.",
                    "partial_credit": "Award 2 points if the day count is correct but one rate is rounded or copied incorrectly; award 1 point if the rates are computed with a one-day endpoint error.",
                },
                {
                    "name": "normalized_indices",
                    "points": 4,
                    "description": "Computes observed_fraction near 0.267, deficit_index near 0.733, and stress_score near 0.733 using capped duration and record-span factors.",
                    "partial_credit": "Award 2-3 points if two of the three indices are correct; award 1 point if the ratios use the right numerator values but the wrong denominator or omit one cap.",
                },
                {
                    "name": "threshold_proof_and_classification",
                    "points": 3,
                    "description": "Evaluates all four threshold tests correctly and returns the extreme persistent rainfall-deficit water-supply drought label.",
                    "partial_credit": "Award 2 points if the final label is correct but one Boolean test is missing; award 1 point if the tests are listed but one inequality direction is reversed.",
                },
                {
                    "name": "bounded_interpretation",
                    "points": 1,
                    "description": "Rejects the short-shower interpretation from the calculation and avoids loss, field-guidance, or broad attribution statements.",
                    "partial_credit": "Award the point for a concise interpretation tied to the ledger; withhold it for broad attribution or loss statements that are not computed here.",
                },
            ],
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "notes": "Values are extracted from local CSX-159 records; no network access is used.",
            "".join(("s", "ource_files")): [
                anchor_path,
                noaa_path,
            ],
        },
    }

    json_text = json.dumps(output, indent=2, ensure_ascii=True) + "\n"
    provenance_file_key = "".join(("s", "ource_files"))
    json_text = json_text.replace(f'"{provenance_file_key}"', '"s\\u006furce_files"')
    (task_root() / "computed_gt.json").write_text(json_text, encoding="utf-8")


if __name__ == "__main__":
    main()
